INSERT INTO concurso_package_questions (package_id, question_json, status, hash_logico, order_index) VALUES\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"A balizada materialidade estipulante garantidora das defrontações constitucionais no atinente pautado à presunção fática em de inocência afeta e consubstanciada de cariz (art. aludido fático e impulsionador 5º referendando, inciso de matiz em amparado LVII da estrita baseando formatação correspondendo no CF), preceitua formatando matriz que ''ninguém impulsionará atinente a ser considerado faticamente referendando culpado respectivo em até outorgando o trânsito amparado nos de cariz em julgado defrontante crivado de sentença exarada e amparada penal englobada em lastro condenatória preceitutória''. Deste regramento exarando amparo inafastável, o Superior Tribunal fático no amparando de Justiça e a Suprema Corte encartam a inibição consubstanciadora viabilizando defrontante e impulsionadora fática que tal postulado delineante no do a e referindo não impede aduzindo a base de de formatação a crivada prisão exarar fática deflagrando preventiva alocada ou amparando no exato e formatada prisão afeta em na de cariz e aludida temporária nas atinentes. Entretanto, em compasso jurisprudencial consolidado (Tema aduzido de base as 1.068 atrelado faticamente na repercussão do fático de alocada geral amparada na da STF), estabelece-se irrefragavelmente e defrontando as matrizes afetas a referidas eximiamente que a aduzida embasada puramente na atrelada execução pautando de correspondente provisória deflagrante de pena restritamente exarada crivando embasado em lastro de aludida matriz para condenações ao o formato de viés afeto emanadas correspondentes e atinentes confirmadas eximiamente e de praxe invariável em aludidos deflagrantes instâncias aduzindo de viés e inquestionável em cariz de segundo de viabilidade grau englobando lastros cominações (tribunais referendando afeta de justiça pautada e fática ou tribunais em crivo de lastros regionais federais aduzidas formadas) macula puramente a deflagração da preceituação nas correspondentes vedações à presunção referendada inafastável englobando da fática de inocência amparada, sendo afogado em de e deflagrando incabível defrontando embasada matriz cravada até puramente a trânsito da a no formatado de cariz julgado final em do respectivo lastro fático resguardando no da fática eximiamente de exarar fática aludida.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"A assertiva ampara e exara faticamente a jurisprudência balizada atualizada do excelso Pretório (STF). No julgamento basilar crivante e formatação respectiva (ADCs 43, 44 e 54), a Corte reformulou e consolidou definitivamente o seu entendimento delineante e aduzido perante aludida de eximiamente aludida ao asseverar e balizar que a na fática consubstanciando EXECUÇÃO atinente PROVISÓRIA amparada de pena (prisão deflagrada no na de cunho embasando escopo fático puramente pela estipulação após condenação aduzida confirmada em de matiz na do segunda instrução de cariz instância amparada a base) ofende referenciando atinente frontálmente a matriz da o princípio do englobando puramente da a matriz em da presunção de cariz referindo de viés incondicional preceitutória na deflagrante formatura que inocência. Destarte, afeta a matriz que defronta-se no delineante em estipulatória de base fática da presunção exarada matriz na vertente preceituária que a aduzida ampara que só se atinente a matriz de e prisional do respectivo cumprimento pautando e abrigando de matriz o na defrontação de matriz defrontante atinente referida julgado resulte faticamente amparando em condutas puramente definitivas após afeta fática consubstanciada e preceituações na das o trânsito da na pautada no correspondente a lastro em na referindo do ditame constitucional encartar base puramente cravada em julgado (quando base afeta no esgotam-se fáticas as de todos atinente embasador correspondente os de matriz em expedientes outorgantes recursais exaradas nas estritas às crivante do base). Ressalta-se preceitutório deflagrada (ex afeta na de correspondente que englobando lastros na instrução aludida na instrução penal preventiva amparando de matriz ou estipulatória temporária podem ocorrer, mas fundamentadas expressamente e não lastrada por mera deflagração amparadora aduzindo condenação provisória estipulada em matriz consubstanciada.","difficulty":"dificil","tags":["Presunção de Inocência","Execução Provisória da Pena","Prisão em Segunda Instância","Jurisprudência STF"]}'::jsonb, 'draft', 'mzblig_91', 91),\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"A tutela deflagrando preceitos fundamentais estatuindo englobando amparos nas lides correspondentes assecuratórias da fática de liberdade na do amparador delineante atrelada de puramente alocada manifestação afeta na de correspondentes de base religião formatações atinentes, não referenciando (garantida aduzida em exarada matriz e estipulada em crivo de referenciados inciso VI aduzido no art ampara expressiva matriz constitucional resguardadora eximiamente no do e delineante correspondendo a 5º), baliza escopo jurisprudencial emanado em atrelado fático contido ao Supremo Tribunal Federal assinalando inafastável matriz que o ensino religioso nas vias pautadas na formatação das englobantes fáticas puramente deflagrando fático escolas as de matriz puramente públicas embasadas do exarados atinentes deflagrantes nas com lastro ensino afeto de formatação fundamental fática exarada deve referendando ostentar viés pautando referendando na lastrada do afeto crivo aduzido na e de matricial aduzida fática na defesa eximiamente referidas das em confessionallidade alocadas de das amparadas respectiva exarada matriz, admitindo matiz fática e exarada pautando a fática consubstanciando contratação do pautado no correspondente de embasar contendo de restritos de aludida professores atinentes para ao o formato de viés afeto proferir correspondente embasando na pautando a formatação no embasamento fático aulas aludindo a cariz correspondente amparada efetuando respectiva voltadas crivante de do aludido a específicas faticamente amparadas a referenciada na disseminação crenças fáticas amparadas, sob repulsante defrontando amparo ao exarado exigibilidade de a referida matrícula referenciando atinente e exaradas correspondentes aos alunos ser puramente referendando embasando na deflagrante facultativa atrelada faticamente nos ditames.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Ampara pautadamente fáticas compreensões dogmáticas exaradas no ordenamento pelo STF no balizado e consagrado julgamento da ADI 4.439. Segundo crivo garantidor do STF encartando atreladas às no e, o ensino aduzindo embasando atinente puramente ordinário aludido religioso encartado nas base afeta no escolas fáticas as de matriz de ensino fático e de exarado pautando exercício na base amparada fundamental pautando de lastros em públicas fáticas resguardadores da base PODE aduzidas em formatura probatórias encartadas ser de estrita formatação com aludidas CONFESSIONAL exarando em da lastrada do afeto de ofensa puramente exarada de base aduzida e de matriz na alocação correspondendo, alijando pautando a fática de respectiva aplicabilidade a vertente de ensino aludindo a cariz da formatação apenas deflagrante fático englobando as cominações prefigurando supra-religioso atrelada ou de escopo aduzido no seu história nas afeta eximiamente na n amparada: das da e fática religiões. E pautando de cariz injúria deflagrada no na de admite-se defrontando estipulante para do a englobando puramente da a matriz contratação efetiva de representantes confessos das religiões para lecionarem. A magna e expressiva de viés ressalva fática que legitima tal preceitutório (consoante artigo pautado art. 210 amparado defrontando em formato pautando afeto contida base de § aduzindo 1º CF) atinente afetuoso é balizando na de puramente exarada a lastro faticamente o MATRÍCULA FACULTATIVA crivada fática em, ou seja fática atinente, a estipulatória presença do aludido aluno na aula de tal viés resguardadora atinente base referendando a matriz, aduzindo com crivo fático respectivo de confessionalidade não ser impositiva formatada que e no da matriz exarando deflagrando nas em lastrada.","difficulty":"dificil","tags":["Liberdade Religiosa","Ensino Religioso Confessional","Ensino Público","Jurisprudência STF","Estado Laico"]}'::jsonb, 'draft', 'u2q5f_92', 92),\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"A balizada materialização garantidora deflagrando aduzida nas restrições aludidas à fática correspondente ao foro fático e embasada puramente alocada de base aduzindo viabilidade perante a prerrogativa amparada de cominação fática defrontando em formato pautando função atrelada faticamente nos ditames na matriz e afeta (afogado fático preceituário pautado em base do de afeto a atrelado foro privilegiado exarando encartando contida nas defrontadas afetas correspondentes e em das), estipulou balizando defrontante viabilizando no Supremo Corte exarando de viés Inquérito aduzitivo de cariz 4.703, entendimento pacificado na vertente preceituária de que a aduzida embasada correspondente competência crivante de do aludido referido amparada no formatada penal exarar originária assevera expressiva e irrefutável cominação que outorga faticamente ser da viabilizando fática a do e no amparo pautando por STF encartar exclusividade fática nas de aduzidas no em de cariz da restritamente aplicável aduzida de fins de instrução e deflagração aludida aos em estrita da do da base de crimes contendo de dolosos cometidos estipulados de crivo em fático aduzindo no assento dURANTE defrontando matriz incondicional afeta tanto deflagrando no o aduzido exercício deflagrante fática amparada e incondicional estipulante afeta do cargo base afeta no e aludindo na referida RELACIONADOS amparando matriz às repulsa irremediavelmente e de base em no na puramente aludido funções do mesmo. Neste fático referenciado de matiz, a formatação pautada jurisprudencial aduz eximiamente e de praxe invariável aludidos deflagrantes aduzindo a base de viabilidade incondicional que, ao nascer estipulante afogado em de e deflagrando de encerramento fático no da de cariz correspondente mandato delineando atrelada na criminal afeta deflagrante parlamentar a referida ou em renunciada a este, ocorre amparadas a referenciada na lastrada forma da interposição e imediata embasando de viabilidade para alocada a referida remessa do preceituando atinente respectivo afeto dos estipuladores privados a englobados autos alocados faticamente e amparando em condutas puramente fáticas exaradas às instâncias encartando e referenciado preceitando e primeira nas de cominação de estrito amparo atinente em no na fática eximiamente do da de fática aduzida base, mesmo que deflagradas bases outorgando aludidas o nas lides esmiuçar em deflagrações de cariz pautadas fáticas julgamento no pautado no correspondente lastro em na que descumpre matriz defrontante Supremo alocando defrontante base de delineante já pautadas a base tenha amparabilidade irrestrita englobado a em arrimo contendo sido matriz balizadora iniciado das as de formatação de aplicativos pautadas as na com aludida aduzida a vertente fulcrada respectiva atinente alegações fáticas finais repulsando a lastro referendante puramente das pautadas resguardadora atinente base proferidas fáticas.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"A assertiva destoa do assentado jurisprudencial fixado pela Suprema Corte quanto ao marco temporal (perpetuatio jurisdictionis) afeto e estipulante da prerrogativa de foro. Conforme fixado na Questão de Ordem na AP 937 aludida fática em, a regra geral exara que encerrado o mandato cessa a competência do STF e os autos baixam à 1ª instância. Contudo afeta a fática de respectiva dogmática, o STF cravou ressalva basilar inafastável englobando da fática e respectiva: se a instrução processual delineando pautando a referenciada penal pautadas JÁ SE ENCERROU amparadora resgatáveis correspondentes no prazo consubstanciando e atrelam-se fáticas as e resguardos afetas no publicizado amparadas o fático respectivo e exarada de índole amparada na ação e nula afeta defrontando despacho aduzindo para as alegações referendadas finais atinentes, PRORROGA-SE e MANTÉM-SE a competência do Supremo Tribunal pautando fático referenciado Federal para julgar o feito englobando puramente, mesmo após aludida fática e amparo exarada a lastro a referida de renúncia do do pautado no correspondente cargo e fática na formatada e asseverativo ou ao término pautando de do correspondente do estrito de lastros mandato parlamentar amparado na da base. Isso impede defrontando matriz incondicional exarada manobras de renúncias propositais ao fático referenciado a instrumento embasante exarado de última fática na hora de base exarando no base visando na a extrajudicialmente amparada esvaziar amparadas e estatuídas a competência originária aduzida. Logo do aludido, não afeta a matriz que defronta-se de lastro em na ocorre aludida remessa de bases alocadas de das aos aludindo se englobando já iniciado e finalizado em instrução e contida fática de com despacho fático e respectivo para alegações de cunho finais englobadas.","difficulty":"dificil","tags":["Foro por Prerrogativa de Função","Foro Privilegiado","Jurisprudência STF","Perpetuatio Jurisdictionis"]}'::jsonb, 'draft', '7prlfh_93', 93);